<?php
declare(strict_types=1); define('SAAS_NO_GLOBAL_NAV',true); require_once __DIR__.'/finance.php'; require_once __DIR__.'/activity.php'; require_finance_admin();
$pdo=db();$date=(string)($_GET['date']??date('Y-m-d'));$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$employee=(int)$_POST['employee_id'];$status=(string)$_POST['status'];$reason=trim((string)($_POST['override_reason']??''));if($reason===''){http_response_code(422);exit('Override reason is required.');}$in=$_POST['check_in']?:null;$out=$_POST['check_out']?:null;$hours=($in&&$out)?round((strtotime($out)-strtotime($in))/3600,2):0;$pdo->prepare('INSERT INTO attendance(employee_id,date,day,check_in,check_out,working_hours,status,remarks) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE day=VALUES(day),check_in=VALUES(check_in),check_out=VALUES(check_out),working_hours=VALUES(working_hours),status=VALUES(status),remarks=VALUES(remarks)')->execute([$employee,$_POST['date'],date('l',strtotime((string)$_POST['date'])),$in,$out,$hours,$status,$reason]);log_activity((int)$_SESSION['user']['id'],'Attendance override: '.$reason,'other',$employee);$date=(string)$_POST['date'];$message='Attendance saved and override logged.';}
$employees=$pdo->query("SELECT id,name FROM users WHERE role='employee' AND active=1 ORDER BY name")->fetchAll();$stmt=$pdo->prepare('SELECT a.*,u.name FROM attendance a JOIN users u ON u.id=a.employee_id WHERE a.date=? ORDER BY u.name');$stmt->execute([$date]);$rows=$stmt->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><title>Attendance</title><link rel="stylesheet" href="assets/css/saas.css"></head><body class="saas-body"><div class="saas-shell"><aside class="saas-sidebar"><div class="brand"><span>MT</span> Mega Techzy</div><a class="saas-nav" href="admin_dashboard.php">▦ <span>Overview</span></a><a class="saas-nav" href="manage_clients.php">♙ <span>Clients</span></a><a class="saas-nav" href="manage_users.php">♟ <span>Users</span></a><a class="saas-nav active" href="admin_attendance.php">◷ <span>Attendance</span></a><a class="saas-nav" href="payroll.php">▤ <span>Payroll</span></a><a class="saas-nav" href="activity_log.php">◌ <span>Activity log</span></a><a class="saas-nav" href="logout.php">↪ <span>Log out</span></a></aside><main class="saas-main"><h1 class="saas-title">Attendance</h1><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><form method="post" class="saas-card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-2"><label>Date</label><input class="form-control" type="date" name="date" value="<?=e($date)?>" required></div><div class="col-md-3"><label>Employee</label><select class="form-select" name="employee_id" required><option value="">Select</option><?php foreach($employees as $employee):?><option value="<?=$employee['id']?>"><?=e($employee['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Status</label><select class="form-select" name="status"><?php foreach(['present','absent','half_day','paid_leave','weekly_off','holiday'] as $status):?><option value="<?=$status?>"><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Check in</label><input class="form-control" type="datetime-local" name="check_in"></div><div class="col-md-2"><label>Check out</label><input class="form-control" type="datetime-local" name="check_out"></div><div class="col-md-6"><label>Override reason</label><input class="form-control" name="override_reason" required></div><div><button class="btn-indigo">Save override</button></div></div></form><section class="saas-card"><table class="saas-table"><thead><tr><th>Employee</th><th>Status</th><th>Check in</th><th>Check out</th><th>Hours</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['name'])?></td><td><?=e(ucwords(str_replace('_',' ',$row['status'])))?></td><td><?=e($row['check_in']??'')?></td><td><?=e($row['check_out']??'')?></td><td><?=e((string)$row['working_hours'])?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
